head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > isPopup]<br/>현재 화면이 팝업으로 열린 창인지 여부를 반환합니다.",
    "validation" : [
        "현재 화면이 팝업이면 true, 아니면 false 를 반환해야 합니다.",
        "isClosest(선택) 파라미터가 true 이면 현재 화면부터 상위 프레임까지 거슬러 올라가면서 팝업 여부를 확인해야 합니다.",
        "isClosest(선택) 파라미터가 false 이면 현재 화면만 팝업 여부를 확인해야 합니다.",
        "isClosest(선택) 생략 시 기본값 false 로 동작해야 합니다.",
        "'Page Scope' 가 적용되어 WebSquare.util.isPopup() 과 달리 파라미터를 추가로 받아야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    var options = {
        id: "isPopup_popup",
        type: "wframePopup",
        width: "700px",
        height: "400px",
        top: "100px",
        left: "100px",
        popupName: "isPopup 테스트 팝업",
        modal: false
    };

    $p.openPopup("/sample/common_link/$p_isPopup_1.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (wframePopup)");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 isPopup() / isPopup(true) 결과를 확인하세요.");
}
